<section><a class="back-link" href="/merchant/customers">← All customers</a><div class="page-heading"><div><p class="eyebrow">Customer profile</p><h1><?= e($customer['name']) ?></h1><p class="muted"><?= e($customer['phone']) ?> · First order <?= e(gmdate('M j, Y',strtotime($customer['first_order_at']))) ?></p></div></div>
<div class="customer-summary"><article class="panel"><span>Completed/non-cancelled orders</span><strong><?= e($customer['order_count']) ?></strong></article><article class="panel"><span>Historical order value</span><strong><?= e($customer['currency_code']?:$store['currency_code']) ?> <?= e($customer['total_value']) ?></strong></article><article class="panel"><span>Last order</span><strong><?= e(gmdate('M j, Y',strtotime($customer['last_order_at']))) ?></strong></article></div>
